"use client";
import { motionTokens, useShouldReduceMotion, useTempoTransition } from "../../utils/motion/index.js";
//#region src/internal/controls/press.ts
const PRESS_TRANSITION = motionTokens.spring.press;
const PRESSED_SCALE = motionTokens.scale.press;
function usePressMotion({ disabled, transition, scale = PRESSED_SCALE } = {}) {
	const reduce = useShouldReduceMotion();
	const spring = useTempoTransition(transition ?? PRESS_TRANSITION);
	if (reduce || disabled) return {};
	return {
		initial: { transform: "scale(1)" },
		whileTap: { transform: `scale(${scale})` },
		transition: spring
	};
}
function usePressedMotion({ isPressed }, { disabled, transition } = {}) {
	const reduce = useShouldReduceMotion();
	const spring = useTempoTransition(transition ?? PRESS_TRANSITION);
	if (reduce || disabled) return {};
	return {
		initial: false,
		animate: { transform: `scale(${isPressed ? PRESSED_SCALE : 1})` },
		transition: spring
	};
}
//#endregion
export { PRESSED_SCALE, PRESS_TRANSITION, usePressMotion, usePressedMotion };
